import math
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st

from solution import get_max_triples


def reference(n):
    a = [i * i - i + 1 for i in range(1, n + 1)]
    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if (a[i] + a[j] + a[k]) % 3 == 0:
                    count += 1
    return count


def residues(n):
    return [(i * i - i + 1) % 3 for i in range(1, n + 1)]


def test_example_n_equals_5():
    assert get_max_triples(5) == 1


def test_example_array_consistency():
    # a = [1, 3, 7, 13, 21] for n=5; only (1, 7, 13) sums to multiple of 3
    a = [i * i - i + 1 for i in range(1, 6)]
    assert a == [1, 3, 7, 13, 21]
    assert (a[0] + a[2] + a[3]) % 3 == 0
    assert get_max_triples(5) == 1


def test_n1_returns_zero():
    assert get_max_triples(1) == 0


def test_n2_returns_zero():
    assert get_max_triples(2) == 0


def test_n3_returns_zero():
    # a=[1,3,7], 1+3+7=11 not multiple of 3
    assert get_max_triples(3) == 0


def test_n4_returns_one():
    assert get_max_triples(4) == 1


def test_n6_returns_four():
    assert get_max_triples(6) == reference(6) == 4


def test_small_values_match_reference():
    for n in range(1, 21):
        assert get_max_triples(n) == reference(n), f"n={n}"


@given(st.integers(min_value=1, max_value=60))
def test_matches_brute_force_reference(n):
    assert get_max_triples(n) == reference(n)


@given(st.integers(min_value=1, max_value=100))
def test_result_is_int_and_nonnegative(n):
    r = get_max_triples(n)
    assert type(r) is int
    assert r >= 0


@given(st.integers(min_value=1, max_value=100))
def test_result_bounded_by_n_choose_3(n):
    r = get_max_triples(n)
    assert r <= math.comb(n, 3) if n >= 3 else r == 0


@given(st.integers(min_value=1, max_value=99))
def test_monotone_nondecreasing(n):
    assert get_max_triples(n + 1) >= get_max_triples(n)


@given(st.integers(min_value=1, max_value=60))
def test_only_residues_zero_and_one_matter(n):
    # a[i] mod 3 is only ever 0 or 1; valid triples are exactly 0+0+0 and 1+1+1
    res = residues(n)
    assert set(res).issubset({0, 1})
    c0 = res.count(0)
    c1 = res.count(1)
    expected = math.comb(c0, 3) + math.comb(c1, 3) if n >= 3 else 0
    assert get_max_triples(n) == expected


@given(st.integers(min_value=3, max_value=60))
def test_increment_equals_new_triples_formed(n):
    # triples for n+1 = triples for n + pairs (i<j<=n) with a[i]+a[j]+a[n+1] %3==0
    a = [i * i - i + 1 for i in range(1, n + 2)]
    added = sum(
        1 for i in range(n) for j in range(i + 1, n) if (a[i] + a[j] + a[n]) % 3 == 0
    )
    assert get_max_triples(n + 1) == get_max_triples(n) + added


def test_no_triples_when_fewer_than_three_elements():
    assert get_max_triples(1) == 0
    assert get_max_triples(2) == 0
